/**
 * Ready sign-in form with login, password, remember-me, forgot link and submit button. Use as the body of an auth page.
 * Note: Field values live inside the component: read them from the submit payload.
 * Note: Translate the texts with labels; the "email" value holds an email or phone.
 */
export interface UiLoginFormProps {
  /** Failure message shown in a danger alert above the fields. */
  error?: string;
  /**
   * Disables the submit button and shows a spinner.
   * @default false
   */
  loading?: boolean;
  /**
   * Show the "Forgot password?" link.
   * @default true
   */
  showForgot?: boolean;
  /**
   * Submit button text. Wins over labels.submit.
   * @default Sign in
   */
  submitLabel?: string;
  /**
   * Texts of the form; any missing key keeps its English default.
   * @default { email: 'Email or phone', password: 'Password', remember: 'Remember device', forgot: 'Forgot password?', submit: 'Sign in' }
   */
  labels?: { email?: string; password?: string; remember?: string; forgot?: string; submit?: string };
  /**
   * Control height, font and padding scale.
   * @default 'md'
   */
  size?: Size;
  /**
   * Called with { email, password, remember } when the form is submitted.
   * @event submit
   */
  onSubmit?: (values: { email: string; password: string; remember: boolean }) => void;
  /**
   * Called when "Forgot password?" is clicked.
   * @event forgot
   */
  onForgot?: () => void;
  children?: ReactNode;
}
export const UiLoginForm: ComponentType<UiLoginFormProps>;

/**
 * Interactive raster map with panning, zoom buttons and clickable markers, using OpenStreetMap data via CARTO tiles.
 * Note: The center and zoom props are initial values; user panning and zooming is kept in internal state. Listen to move/zoom to track it.
 * Note: Drag or touch to pan, wheel or double click to zoom around the pointer. The tile theme follows the page data-theme after mount (light tiles on the server render) unless theme or style is set.
 * Note: Tiles come from a third-party CDN, so it needs network access.
 */
export interface UiMapProps {
  /**
   * Initial center latitude.
   * @default 21.4225
   */
  lat?: number;
  /**
   * Initial center longitude.
   * @default 39.8262
   */
  lon?: number;
  /**
   * Initial zoom level; the zoom buttons clamp it to 3..18.
   * @default 14
   */
  zoom?: number;
  /**
   * Pins. label is the tooltip, icon defaults to "map-pin".
   * @default []
   */
  markers?: { lat: number; lon: number; label?: string; icon?: string; tone?: 'brand' | 'sky' | 'success' | 'warning' | 'danger' | 'neutral' }[];
  /**
   * Pixel width used to compute which tiles to load; the map element itself fills its container.
   * @default 640
   */
  width?: number;
  /**
   * Height in px.
   * @default 360
   */
  height?: number;
  /** Tile theme. If omitted, dark is used when the page is inside a dark data-theme. */
  theme?: 'light' | 'dark';
  /** CARTO tile style path, for example "light_all" or "dark_all". Overrides theme. */
  style?: string;
  /**
   * aria-label of the map region.
   * @default 'Map'
   */
  label?: string;
  /**
   * Accessible names of the zoom buttons.
   * @default { zoomIn: 'Zoom in', zoomOut: 'Zoom out' }
   */
  labels?: { zoomIn?: string; zoomOut?: string };
  /**
   * Called with the marker object when a marker is clicked.
   * @event select
   */
  onSelect?: (marker: NonNullable<UiMapProps['markers']>[number]) => void;
  /**
   * Called with { lat, lon, zoom } while the user pans or zooms (drag, touch, wheel, double click or the +/- buttons).
   * @event move
   */
  onMove?: () => void;
  /**
   * Called with the new zoom level when it changes.
   * @event zoom
   */
  onZoom?: () => void;
  children?: ReactNode;
}
export const UiMap: ComponentType<UiMapProps>;

/**
 * Static vertical list of actions rendered inline; use in sidebars and custom popovers.
 * Note: Always visible unless open is set. For a self-toggling menu use Dropdown, for a right-click menu use ContextMenu.
 */
export interface UiMenuProps {
  /**
   * Menu entries. Item fields: label, value (passed to select), icon (icon name), shortcut (kbd hint on the right), tone "danger" (red), disabled true (dimmed, not clickable), onClick (called with the item when clicked, before the select event), separator true (renders a divider; other fields ignored).
   * @default []
   */
  items?: { label: string; value?: string; icon?: string; shortcut?: string; tone?: 'danger'; disabled?: boolean; onClick?: (item: any) => void; separator?: boolean }[];
  /** Optional. false renders nothing, true shows the menu; leave unset for an always visible menu. */
  open?: boolean;
  /**
   * Scale of row height and text.
   * @default 'md'
   */
  size?: Size;
  /**
   * Called with the item value when an entry is clicked.
   * @event select
   */
  onSelect?: (value: string) => void;
  /**
   * Called on outside click or Escape while open is true. Pass it as onClose.
   * @event close
   */
  onClose?: () => void;
  children?: ReactNode;
}
export const UiMenu: ComponentType<UiMenuProps>;

