/**
 * Guided product tour that dims the page, highlights a target element and shows a step popover.
 * Note: Keyboard: ArrowRight/ArrowLeft go to the next/previous step (reversed in RTL), Escape closes. Focus is not moved, so the page stays usable.
 * Note: Targets are looked up with document.querySelector and scrolled into view.
 * Note: The internal step resets to 0 whenever the tour closes.
 */
export interface UiTourProps {
  /**
   * Shows the tour when true; renders nothing when false.
   * @default false
   */
  open?: boolean;
  /**
   * Steps. target is a CSS selector of the element to highlight; without it the step is shown centered over a full dim.
   * @default []
   */
  steps?: { target?: string; title: string; text: string }[];
  /** Controlled zero-based step index. When omitted the tour keeps it internally (reset to 0 on close). Update it from the step event. */
  step?: number;
  /**
   * Called on the close icon, the Escape key and after Finish on the last step.
   * @event close
   */
  onClose?: () => void;
  /**
   * Called with the new zero-based step index on Next, Back and the arrow keys.
   * @event step
   */
  onStep?: (index: number) => void;
  children?: ReactNode;
}
export const UiTour: ComponentType<UiTourProps>;

